const VIEW = { full: "-93.92 -139.32 1314.65 1314.65", header: "-58.77 -110.77 1257.53 1257.53" };

/**
 * The mark, as the contract reads it. Only the orbit is paced by the turn, so only the orbit's
 * phase is carried across a change. The colours change with the state, which is what survives
 * reduced motion.
 */
const SPEC: MarkSpec = {
  id: "kawaii-tilt",
  beads: 7,
  paced: /^ct-[tnf]$/,
  liveClass: "cm-live",
  look: {
    rest: { "--ct-c0": "oklch(0.86 0.07 350)", "--ct-c1": "oklch(0.85 0.06 300)", "--ct-c2": "oklch(0.89 0.07 165)", "--ct-c3": "oklch(0.92 0.07 95)", "--ct-c4": "oklch(0.87 0.06 230)", "--ct-tw": "7s" },
    live: { "--ct-c0": "oklch(0.72 0.19 355)", "--ct-c1": "oklch(0.66 0.18 300)", "--ct-c2": "oklch(0.78 0.16 165)", "--ct-c3": "oklch(0.86 0.17 90)", "--ct-c4": "oklch(0.72 0.15 235)", "--ct-tw": "1.1s" },
  },
  turnVar: "--ct-turn",
  paperVar: "--ct-paper",
  view: VIEW,
};

export type KawaiiTiltMarkProps = MarkProps;

export function KawaiiTiltMark(props: KawaiiTiltMarkProps) {
  const m = useMark(SPEC, props);
  // Memoised as an OBJECT, not a string: React 19 diffs dangerouslySetInnerHTML by identity, and a
  // fresh object every render would rebuild the markup and restart every animation.
  const body = useMemo(
    () => ({ __html: BODY[m.weight].replaceAll("__cmid__", `ct${m.uid}-`) }),
    [m.weight, m.uid],
  );
  return (
    <svg {...m.root}>
      <style>{STYLE}</style>
      <g className={m.live ? undefined : "ct-drift"} dangerouslySetInnerHTML={body} />
    </svg>
  );
}
